    { id: 3, title: "Python and JS", body: "Both languages are great" },
  ];
  const result = searchNotes(notes, "python");
  expect(result).toHaveLength(2);
  expect(result[0].title).toBe("Python tips");
  expect(result[1].title).toBe("Python and JS");
});

