    { id: 1, title: "Python Tips", body: "Learn Python well" },
    { id: 2, title: "JAVASCRIPT BASICS", body: "JS is fun" },
  ];
  const result = searchNotes(notes, "PYTHON");
  expect(result).toHaveLength(2);
});

